<script setup lang="ts">
import { computed, ref } from 'vue'
import { t } from '../../i18n'
import { composePorts, configValues, iptablesRules, ufwRules, type PortSpec } from './snippets'

const minecraft = ref(25565)
const web = ref(24454)
const copied = ref('')

const spec = computed<PortSpec>(() => ({
  minecraft: Number(minecraft.value) || 0,
  web: Number(web.value) || 0,
}))

const blocks = computed(() => [
  { id: 'ufw', title: t('ports.ufw'), text: ufwRules(spec.value) },
  { id: 'iptables', title: t('ports.iptables'), text: iptablesRules(spec.value) },
  { id: 'compose', title: t('ports.compose'), text: composePorts(spec.value) },
  { id: 'config', title: t('ports.config'), text: configValues(spec.value) },
])

async function copy(id: string, text: string) {
  await navigator.clipboard.writeText(text)
  copied.value = id
  setTimeout(() => {
    copied.value = ''
  }, 1500)
}
</script>

<template>
  <div class="stack">
    <header>
      <h1>{{ t('ports.title') }}</h1>
      <p class="muted">{{ t('ports.lead') }}</p>
    </header>

    <section class="card">
      <div class="grid ports">
        <label>
          <span>{{ t('ports.mc') }}</span>
          <input v-model.number="minecraft" type="number" min="1" max="65535" />
        </label>
        <label>
          <span>{{ t('ports.web') }}</span>
          <input v-model.number="web" type="number" min="1" max="65535" />
        </label>
      </div>
      <p class="note">{{ t('ports.note') }}</p>
    </section>

    <section v-for="block in blocks" :key="block.id" class="card">
      <div class="row head">
        <h2>{{ block.title }}</h2>
        <button type="button" class="ghost" @click="copy(block.id, block.text)">
          {{ copied === block.id ? t('ports.copied') : t('ports.copy') }}
        </button>
      </div>
      <pre>{{ block.text }}</pre>
    </section>
  </div>
</template>

