/**
 * Generates copy-paste firewall snippets. Pure string building, no network.
 *
 * Only ports the setup actually uses: the Minecraft port, the web port for
 * TCP signalling and the SVC mod voice port. Browser audio is WebRTC over
 * short-lived outbound UDP ports, so there is no inbound WebRTC port.
 */
export interface PortSpec {
  minecraft: number
  web: number
}

const lines = (...parts: string[]) => parts.join('\n')

export function ufwRules(spec: PortSpec): string {
  const rules = [
    `ufw allow ${spec.minecraft}/tcp   # Minecraft`,
    `ufw allow ${spec.web}/tcp   # web + signalling`,
    `ufw allow ${spec.web}/udp   # SVC voice (mod)`,
  ]
  rules.push('ufw enable')
  return lines(...rules)
}

export function iptablesRules(spec: PortSpec): string {
  const rules = [
    `iptables -A INPUT -p tcp --dport ${spec.minecraft} -j ACCEPT`,
    `iptables -A INPUT -p tcp --dport ${spec.web} -j ACCEPT`,
    `iptables -A INPUT -p udp --dport ${spec.web} -j ACCEPT`,
  ]
  rules.push('# persist with iptables-persistent or your firewall manager')
  return lines(...rules)
}

export function composePorts(spec: PortSpec): string {
  const ports = [
    `      - "${spec.minecraft}:${spec.minecraft}/tcp"`,
    `      - "${spec.web}:${spec.web}/tcp"`,
    `      - "${spec.web}:${spec.web}/udp"`,
  ]
  return lines('services:', '  minecraft:', '    ports:', ...ports)
}

export function configValues(spec: PortSpec): string {
  return `web.port = ${spec.web}`
}
